export function NotificationsPanel({
  suiteId,
  canManage,
}: {
  suiteId: string;
  canManage: boolean;
}) {
  const { state, reload } = useAsyncData(() => getNotifications(suiteId));

  return (
    <Flex vertical gap={16}>
      <Card
        size="small"
        title={
          <Flex vertical gap={2}>
            <Typography.Text strong>Legacy per-suite webhook</Typography.Text>
            <Typography.Text type="secondary" style={{ fontSize: 12, fontWeight: 400 }}>
              Send this suite's run outcomes to Microsoft Teams, Slack, or email.
            </Typography.Text>
          </Flex>
        }
      >
        {state.status === 'loading' ? (
          <Spin description="Loading notifications…" />
        ) : state.status === 'error' ? (
          <Alert
            type="error"
            showIcon
            title="Failed to load notifications"
            description={state.error}
          />
        ) : (
          <NotificationsForm
            // Remount on a config change so the form re-seeds from the loaded values (render-phase
            // reset, no setState-in-effect); an unchanged reload keeps the same key.
            key={
              `${state.data.enabled}:${state.data.alert_on}:${state.data.has_webhook}` +
              `:${state.data.has_slack_webhook}:${state.data.email_recipients ?? ''}`
            }
            suiteId={suiteId}
            canManage={canManage}
            initialEnabled={state.data.enabled}
            initialAlertOn={state.data.alert_on}
            hasWebhook={state.data.has_webhook}
            hasSlackWebhook={state.data.has_slack_webhook}
            initialEmail={state.data.email_recipients ?? ''}
            onChanged={reload}
          />
        )}
      </Card>
      <ChannelPicker suiteId={suiteId} canManage={canManage} />
    </Flex>
  );
}

/**
 * Reusable-channel linking (#1761, admin-managed destinations from Settings → Notifications).
 * Coexists with the legacy per-suite webhook above rather than replacing it — both paths deliver
 * independently server-side.
 */
function ChannelPicker({ suiteId, canManage }: { suiteId: string; canManage: boolean }) {

import { expect, test } from '@playwright/test';

// NotificationsPanel on the seeded suite's detail page: per-suite alerting config (W6 — fronts
// notification_service).
test.describe('Suite notifications panel', () => {
  const card = (page: import('@playwright/test').Page) =>
    page.locator('.ant-card').filter({ hasText: 'run outcomes to Microsoft Teams' });

  const openSuite = async (page: import('@playwright/test').Page) => {
    await page.goto('/suites');
    await page.getByText('Orders quality').click();
    await expect(page).toHaveURL(/\/suites\/[0-9a-f-]+$/);
    await expect(card(page).getByText('Notifications', { exact: true })).toBeVisible();
  };

  test('configure threshold routing and persist it across a reload', async ({ page }) => {
    await openSuite(page);
    const panel = card(page);

    // Snapshot the config so the spec doesn't permanently mutate the seeded
    // suite (alerting behavior for every later dev-stack run); restored below.
    const suiteId = page.url().match(/suites\/([0-9a-f-]+)/)?.[1];
    const before = await (await page.request.get(`/api/v1/suites/${suiteId}/notifications`)).json();

    // Deterministic target state: enabled + "On warn and worse".
    const enable = panel.getByRole('switch', { name: 'Enable notifications' });
    if (!(await enable.isChecked())) {
      await enable.click();
    }
    // Keyboard-only selection: rc-virtual-list parks option nodes in an off-viewport measurement
    // container, so clicking an option by role is flaky (element "outside of the viewport").
    const OPTIONS = ['On fail / critical', 'On warn and worse', 'Always (every run)'];
    const target = OPTIONS.indexOf('On warn and worse');
    // The select renders its current value as visible text in the panel;
    // default (no config yet) is the first option.
    let current = 0;
    for (let i = 0; i < OPTIONS.length; i++) {
      if ((await panel.getByText(OPTIONS[i], { exact: true }).count()) > 0) {
        current = i;
        break;
      }
    }

    const threshold = panel.getByRole('combobox');
    await threshold.click();
    await expect(page.locator('.ant-select-dropdown').last()).toBeVisible();
    for (let i = 0; i < Math.abs(target - current); i++) {
      await threshold.press(target > current ? 'ArrowDown' : 'ArrowUp');
    }
    await threshold.press('Enter');

    await panel.getByRole('button', { name: 'Save' }).click();
    await expect(page.getByText('Notifications saved')).toBeVisible();

    // Reload → the form re-seeds from the API with the saved values.
